// Turns Aggregate's invoice list into one summary per company. All amounts come from Aggregate, not the AI.
const parse = (item, key) => {
  const text = (item.json.content ?? []).map((c) => (typeof c.text === 'string' ? c.text : JSON.stringify(c.text))).join('\n');
  const at = text.indexOf('{"' + key + '"');
  if (at < 0) throw new Error('Aggregate did not return ' + key + ': ' + text.slice(0, 300));
  return { note: text.slice(0, at).trim(), data: JSON.parse(text.slice(at)) };
};
const money = (amount, currency, signed = false) => {
  const n = Number(amount);
  const v = Math.abs(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const body = currency === 'USD' ? '$' + v : v + ' ' + currency;
  return signed ? (n < 0 ? '-' : '+') + body : body;
};
const s = $('Settings').first().json;
const { data } = parse($input.first(), 'owed_to_you');
const found = data.owed_to_you ?? {};
const invoices = (found.invoices ?? []).filter((i) => Number(i.outstanding.amount) >= s.minInvoiceAmount);
const companies = {};
for (const i of invoices) {
  const co = (companies[i.company] ??= { company: i.company, customers: {} });
  const key = i.counterparty + '|' + i.outstanding.currency;
  const c = (co.customers[key] ??= { customer: i.counterparty, currency: i.outstanding.currency, cents: 0, invoices: [], oldest_days: 0 });
  c.cents += Math.round(Number(i.outstanding.amount) * 100);
  c.invoices.push(i.number);
  c.oldest_days = Math.max(c.oldest_days, i.days_overdue);
}
const summary = Object.values(companies).map((co) => ({
  company: co.company,
  customers: Object.values(co.customers).sort((a, b) => b.cents - a.cents).map((c) => ({ customer: c.customer, overdue: money(c.cents / 100, c.currency), overdue_cents: c.cents, currency: c.currency, invoices: c.invoices, oldest_days: c.oldest_days })),
}));
const more = (found.total_count ?? 0) > (found.invoices ?? []).length ? found.total_count - found.invoices.length : 0;
return [{ json: { summary, count: invoices.length, more, as_text: JSON.stringify(summary.map((co) => ({ company: co.company, customers: co.customers.map(({ overdue_cents, currency, ...c }) => c) }))) } }];

