// Builds the Slack message. Customer lines come from Aggregate; the AI's picks are kept only if they name a customer on the list.
const { summary, more } = $('Build overdue list').first().json;
const picks = $json.output?.chase_first ?? [];
const known = new Set(summary.flatMap((co) => co.customers.map((c) => co.company + '|' + c.customer)));
const lines = ['*Overdue invoices*'];
for (const co of summary) {
  const byCur = {};
  let n = 0;
  for (const c of co.customers) { byCur[c.currency] = (byCur[c.currency] ?? 0) + c.overdue_cents; n += c.invoices.length; }
  const total = Object.entries(byCur).map(([cur, cents]) => (cur === 'USD' ? '$' + (cents / 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : (cents / 100).toFixed(2) + ' ' + cur)).join(' + ');
  lines.push(`*${co.company}*: ${total} across ${n} invoice${n === 1 ? '' : 's'}`);
  for (const c of co.customers) lines.push(`  • ${c.customer}: ${c.overdue}, ${c.invoices.length} invoice${c.invoices.length === 1 ? '' : 's'}, oldest ${c.oldest_days} days overdue`);
}
const kept = picks.filter((p) => known.has(p.company + '|' + p.customer)).slice(0, 3);
if (kept.length) {
  lines.push('*Chase first*');
  for (const p of kept) lines.push(`  • ${p.customer} (${p.company}): ${p.reason}`);
}
if (more) lines.push(`${more} more overdue invoices weren't read; raise the limit in Get overdue invoices.`);
return [{ json: { message: lines.join('\n') } }];
